### Running the Kernel

Given the grid dimension `grid(4, 1, 1)`，let's run the kernel and observe the values of `gridDim.x` for the blocks `(0, 0, 0)` and `(3, ₀, ₀)`.

Here is the kernel code for reference:

```cpp
__global__ void add(float* left, float* right, float* output) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    output[idx] = left[idx] + right[idx];
}

__global__ void test_grid_dim() {
    printf("Block (%d, %d, %d): gridDim.x = %d\\n", blockIdx.x, blockIdx.y, blockIdx.z, gridDim.x);
}

int main() {
    const int size = 4;
    const int block_size = 1;

    float *left, *right, *output;
    cudaMalloc(&left, size * sizeof(float));
    cudaMalloc(&right, size * sizeof(float));
    cudaMalloc(&output, size * sizeof(float));

    // Initialize left and right arrays
    for (int i = 0; i < size; ++i) {
        left[i] = static_cast<float>(i);
        right[i] = static_cast<float>(i) + 0.5f;
    }

    dim3 grid(size, 1, 1);
    dim3 block(block_size, 1, 1);

    add <<<grid, block>>> (left, right, output);

    // Launch the test kernel
    test_grid_dim <<<grid, block>>> ();

    cudaFree(left);
    cudaFree(right);
    cudaFree(output);

    return 0;
}
```

